    "literal.51ec1975eab6":
      "Bezeroaren datuak merkatua kudeatzeko erabiltzen dira, ez ezkutatzeko.",
    "literal.66fa2631d38c": "Bezeroen iritziak",
    "literal.063d09a5d285": "Bezeroek ere erosi zituzten",
