    "literal.7317866c3efa": "Eman blog-argitalpena",
    "literal.8dbb6170403d": "Eman blog-argitalpen bat True Grit komunitateari.",
    "literal.16975062a8e1": "Eman mezu bat komunitateari",
    "literal.962599197cf0": "Oraintxe ezaguna",
