    "literal.e2fe8b87e36d": "Argitaratu bloga",
    "literal.d53e639594d0": "Argitaratu errezeta",
    "literal.d7432cda8e62": "Posta-kodea",
    "literal.e6038288c7df": "Elikagaien gida praktikoak",
    "literal.4c4993d61c7c":
      "Elikagai ekologikoak ondo erosi, gordetzeko eta ondo prestatzeko gida praktikoak.",
    "literal.70771ddd7dc6": "Eposta elektronikoa nahiago?",
    "literal.1e08814104bd": "Prestatzeko denbora (min)",
    "literal.50f94286ba30": "Aurrekoa",
    "literal.93ba97d19f91": "Prezioa bereizita",
    "literal.bf631b74c3f4": "Prezioak eta zergak",
    "literal.91ef909d6aba":
      "Prezioak zerbitzariaren aldetik berriro balioztatzen dira zure eskaera berretsi baino lehen.",
    "literal.3538b2f8ee7c":
      "Prezioak Indiako errupiatan erakusten dira, kontrakoa adierazi ezean. Azken zergak, entrega-gastuak eta deskontuak ordainketa egitean berresten dira.",
    "literal.acc6e565014a": "Eskaera baten ordainagiria inprimagarria",
    "literal.a9a96ec01949": "Lehenengo",
    "literal.e39c15d30393": "Inprimatu/Gorde __TGBRAND",
    "literal.7ceacdcaab4c": "Pribatutasun politika",
    "literal.4c2584d850a7": "Pribatutasun-eskaera?",
    "literal.2447d981ade3": "Priya Sharma",
    "literal.9456d3ce22ab": "Jarraitu ordainketarekin",
    "literal.e63451d3cf90": "Prozesatzen",
    "literal.38a007151abe": "produktua",
    "literal.9ea4925ada6b": "Produktuen erabilgarritasuna",
    "literal.e735e2016327":
      "Produktu-orrietan baserria, ziurtagiria, uzta eta ontziratzeari buruzko informazioa dago. Nekazarien orrialdeak egungo bazkide-ustiategi guztiak zerrendatzen ditu.",
    "literal.fe0a091fdbfb": "Produktuak",
    "literal.1e5ff9e500c2": "Kantitatea",
    "literal.fb6b8652ec52": "Kalitate arazoa",
    "literal.44f6af694554": "Kantitatea",
    "literal.4d86ec50f067": "Eskaera, baserri, produktu edo lankidetza bati buruzko galderak?",
    "literal.d0530bf237b3": "Galderak, zintzo erantzunak",
    "literal.e7e976834f93":
      "Laguntza azkarra True Grit eskaera, entrega, itzulket, kontu eta produktuen galderetarako.",
    "literal.6437b7bf6558": "Balorazioa",
    "literal.a3ccb3302793": "Razorpay",
    "literal.8285166982ff": "Razorpay ordainketa",
