    "literal.20010c3fde52":
      "métodes realistes i flexibles, de manera realista i flexible. està en temporada.",
    "literal.56b189be7ddd": "Tanca el tauler del compte",
    "literal.940323c22878": "Tanca les categories",
    "literal.e3896a930398": "Tanca la finestra",
    "literal.118a99898154": "comenta",
    "literal.380b7207a341": "Camins d'ajuda comuns",
    "literal.bfd58ee3a270": "Comunitat",
    "literal.ee084583c92d": "Debat de la comunitat",
    "literal.54840b9b41e2": "Completa la teva comanda",
