    "literal.ffe648011733": "Ukuhanjiswa & nentlawulo",
    "literal.beacd3ba4e7b": "Idilesi yonikezelo",
    "literal.a9673b5ed2d0": "Ukuhanjiswa kunye nomngcipheko",
    "literal.e841b09cc28f": "Iindawo zokuhanjiswa",
    "literal.63cd3f785612": "Imo yedemo — akukho SMS ithunyelwayo. Sebenzisa ikhowudi",
    "literal.9d3f87b388e0": "Imo yedemo — setha",
