    "literal.c7199d9e9593": "Ugcino",
    "literal.29160ec9d703": "Buyisela ubume besicelo:",
    "literal.9582a02f141f": "Ibuyisela",
    "literal.3322a2092ac9": "Imbuyekezo kunye nembuyekezo",
