    "literal.8dbb6170403d": "Blog postini True Grit hamjamiyatiga jo‘natish.",
    "literal.16975062a8e1": "Hamjamiyatga post jo‘natish",
    "literal.962599197cf0": "Hozir mashhur",
    "literal.c0b5556d773c": "Bu hafta mashhur",
