    "literal.63cd3f785612": "Demo tertibi - SMS iberilmeýär. Kod ulanyň",
    "literal.9d3f87b388e0": "Demo tertibi - düzüldi",
    "literal.eb3c62690ec9": "bölümi",
    "literal.0c727f1d35cd": "Bölümler",
    "literal.055f4ce44734": "Iýmit bellikleri (vergi aýry, islege bagly)",
    "literal.b524936d7aa1": "Arzanladyş",
    "literal.c255751d518c": "çekişme",
    "literal.8fb937b602b4": "Ara alyp maslahatlaşmak",
