    "literal.932fc13e7f6c": "Umutwe (ubishaka)",
    "literal.081c47cb26cd": "gushyira amabwiriza nyayo.",
    "literal.b25928c69902": "Igiteranyo",
    "literal.e2eaab23b765": "Kurikirana ibiryo byawe",
    "literal.9dc70a3eac68": "Kurikirana kuri tombora",
    "literal.b196a0ed93a5": "Kurikirana ibyatanzwe",
    "literal.39f6c3e75a47": "Kurikirana inyandiko za blog hamwe nibisubizo watanze.",
    "literal.38dd6254e365": "Kurikirana ibyo wategetse",
    "literal.654aec82f8c3": "Inkunga iboneye",
    "literal.a2550376c3a8": "Kugenda ku isoko",
    "literal.b8578758a1b9": "True Grit umuryango",
    "literal.f157fa11f74f":
      "True Grit ihuza ingo nimirima yemewe yemewe, itunganya ibyiciro bito hamwe nibisarurwa byigihe bishobora gukomoka kumasoko kugeza kubitanga.",
    "literal.e3d711daf84f": "True Grit murugo",
    "literal.04b9fb437bb4":
      "True Grit ni isoko kama ikurikirana yubatswe hafi yimirima yagenzuwe, gusarura ibihe nibiryo byukuri.",
    "literal.cc30acec73e2":
      "True Grit igaruka, gusimbuza no gusubiza politiki kubintu bishya na pantry.",
    "literal.4d697a97a18a": "Kwizera ntabwo ari ijambo ryamamaza hano. Ni urutonde.",
    "literal.2437394cdf1e": "Gerageza “ragi”, “ibishyimbo by'impyiko” cyangwa “Devika”…",
    "literal.0a268c60409d":
      'Gerageza ijambo ryoroshye - natwe twumva amazina asanzwe nka "urutoki urutoki" kuri ragi.',
    "literal.57cbd9d1e918": "Ku wa kabiri",
    "literal.0f470d23d902": "Iminsi ibiri y'akazi",
    "literal.f6b935ab3371": "Igice",
    "literal.39f9b40b018a": "Koresha aderesi zitandukanye",
    "literal.f2b97b7897fc": "Koresha kode",
    "literal.16f5da7600d5":
      "Koresha menu ya konte mumutwe kugirango winjire hamwe na Google cyangwa imeri yawe, hanyuma usubire hano kugirango utumire. Igitebo cyawe cyarakijijwe.",
    "literal.127a9193bea6":
      "Koresha urupapuro rwo kugaruka kubintu byangiritse, byabuze, bitari byo cyangwa munsi yibicuruzwa bisanzwe.",
    "literal.f1b90a3141d6": "Ibisubizo byingirakamaro kubiryo ugura mubyukuri",
