    "literal.b227f5879bde": "Kuponi khodi",
    "literal.d62a58df78aa":
      "Zokonda zamsika zosankhidwa pamtengo woikika — ziwonjezedwa mudengu lanu pamodzi, kungodina kamodzi.",
    "literal.68ce4efceb7e": "Zomwe zimakonda pamsika, zogulidwa limodzi pamtengo woikika.",
    "literal.349c135f2f55": "Zokolola zapano",
    "literal.2ce2c48f1d19": "Akaunti yamakasitomala",
    "literal.51ec1975eab6":
      "Zida zamakasitomala zimagwiritsidwa ntchito poyendetsa msika, osati kubisa.",
    "literal.66fa2631d38c": "Ndemanga zamakasitomala",
    "literal.063d09a5d285": "Makasitomala adagulanso",
